/**
 * PSE EDGE Fundamentals Provider
 *
 * Reads data/pse-fundamentals.json (generated by scripts/scrape-pse-fundamentals.ts
 * from real PSE EDGE disclosure filings — each record carries the sourceUrl of
 * the filing it was read from).
 *
 * The file has covered 270 companies since August 2026, but nothing under src/
 * consumed it: only the scraper that writes it referenced the path. Without it
 * stockHandler had no fundamentals at all when the database was unavailable,
 * so P/E, P/B, ROE and debt/equity came back null and every factor score was
 * unrated for want of inputs.
 *
 * Monetary figures are in MILLIONS of PHP, as reported in the filings.
 * Ratios (eps, roe, debtToEquity) are as-reported values, not percentages of
 * anything derived here.
 *
 * Same honesty rule as the sibling adapters: a missing figure stays null and
 * is never defaulted, so a company with no filing is scored as unrated rather
 * than as a zero.
 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

export interface PseFundamentalsRecord {
  symbol: string;
  /** Reporting period of the source filing, e.g. "Jun 30, 2026". */
  asOfPeriod: string | null;
  totalAssets: number | null;
  totalLiabilities: number | null;
  totalEquity: number | null;
  netIncome: number | null;
  revenue: number | null;
  eps: number | null;
  sharesOutstanding: number | null;
  operatingIncome: number | null;
  roe: number | null;
  debtToEquity: number | null;
  sourceUrl: string | null;
  scrapedAt: string | null;
}

type FundamentalsMap = Record<string, PseFundamentalsRecord>;

let cache: FundamentalsMap | null = null;

function loadMap(): FundamentalsMap {
  if (cache !== null) return cache;
  let loaded: FundamentalsMap = {};
  try {
    const raw = readFileSync(resolve(process.cwd(), 'data/pse-fundamentals.json'), 'utf-8');
    const results = JSON.parse(raw).results ?? {};
    // Entries for companies with no disclosure are stored as { error: ... };
    // keep only real records so callers never see a partial shape.
    for (const [symbol, value] of Object.entries(results as Record<string, unknown>)) {
      const record = value as PseFundamentalsRecord & { error?: string };
      if (record && !record.error && record.symbol) loaded[symbol] = record;
    }
  } catch {
    // Not scraped yet — treat as "no real data", not an error.
  }
  cache = loaded;
  return loaded;
}

/** Real reported fundamentals for a symbol, or null. */
export function getPseFundamentals(symbol: string): PseFundamentalsRecord | null {
  return loadMap()[symbol.toUpperCase()] ?? null;
}

/**
 * Months of trading covered by a filing's reporting period.
 *
 * PSE EDGE disclosures are overwhelmingly interim: of the 268 records in the
 * file, 210 cover the six months to 30 June and only one is a full year. Flow
 * figures (EPS, revenue, net income, ROE) are therefore for part of a year,
 * and using them as annual makes a P/E roughly twice what it should be —
 * BDO computed to 31.8x against a real trailing multiple near 10x.
 *
 * Returns null when the period cannot be read, so callers skip the metric
 * rather than annualise by a guessed factor.
 */
export function periodMonths(asOfPeriod: string | null | undefined): number | null {
  if (!asOfPeriod) return null;
  const month = new Date(asOfPeriod).getMonth();
  if (Number.isNaN(month)) return null;
  // Fiscal years vary, but PSE issuers report cumulative year-to-date figures,
  // so the calendar month of the period end gives the months elapsed.
  return month + 1;
}

/** Scale a year-to-date flow figure to a full-year run rate. */
function annualise(value: number | null, asOfPeriod: string | null): number | null {
  if (value === null) return null;
  const months = periodMonths(asOfPeriod);
  if (months === null || months <= 0) return null;
  return (value * 12) / months;
}

/**
 * Annualised EPS from the latest filing, or null.
 * Note this is a run-rate extrapolation from year-to-date earnings, not a
 * trailing-twelve-month figure — earnings are assumed evenly distributed.
 */
export function getAnnualisedEps(symbol: string): number | null {
  const r = getPseFundamentals(symbol);
  if (!r) return null;
  return annualise(r.eps, r.asOfPeriod);
}

/** Annualised return on equity (%), or null. */
export function getAnnualisedRoe(symbol: string): number | null {
  const r = getPseFundamentals(symbol);
  if (!r) return null;
  const value = annualise(r.roe, r.asOfPeriod);
  return value === null ? null : Math.round(value * 100) / 100;
}

/** Net margin (%) from reported revenue and net income, or null. */
export function getNetMargin(symbol: string): number | null {
  const r = getPseFundamentals(symbol);
  if (!r || !r.revenue || !r.netIncome) return null;
  if (r.revenue === 0) return null;
  return Math.round((r.netIncome / r.revenue) * 10000) / 100;
}

/** Book value per share requires shares outstanding, which filings omit. */
export function getPbRatio(symbol: string, _price: number): number | null {
  const r = getPseFundamentals(symbol);
  if (!r?.totalEquity || !r.sharesOutstanding) return null;
  const bookPerShare = (r.totalEquity * 1e6) / r.sharesOutstanding;
  if (bookPerShare <= 0) return null;
  return Math.round((_price / bookPerShare) * 100) / 100;
}

/**
 * P/E against annualised EPS. Dividing by a year-to-date EPS would inflate the
 * multiple by 12/months — the reason this returns the annualised figure.
 */
export function getPeRatio(symbol: string, price: number): number | null {
  const eps = getAnnualisedEps(symbol);
  if (eps === null || eps <= 0 || !price) return null;
  return Math.round((price / eps) * 100) / 100;
}

/** Clears the module cache so a regenerated file is picked up. */
export function reloadPseFundamentals(): void {
  cache = null;
}
